# Reload and parse the full grid data from session log
import os, re, json

d = os.environ.get('RLM_SESSION_DIR', '')
if d:
    base = os.path.basename(d)
    session_file = f'{d}/../../sessions/{base}.jsonl'

    with open(session_file) as f:
        lines = f.readlines()

    # Find all demo pairs
    grids = {}
    current_grid = None
    current_key = None
    row_count = 0

    for line in lines:
        try:
            data = json.loads(line)

            # Check for custom message types that might contain grids
            if data.get('type') == 'custom_message':
                content = data.get('content', '')

                # Look for Demo pair patterns
                match = re.search(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):', content)
                if match:
                    key, h, w = match.groups()
                    current_key = key
                    row_count = 0

                    # Parse subsequent rows until we hit another block or end
                    rest = content[match.end():].split('\n')
                    valid_rows = []

                    for row_str in rest:
                        row_str = row_str.strip()
                        if not row_str:
                            continue
                        # Try to parse as a row of digits
                        if re.match(r'^\d+\s+', row_str):
                            parts = row_str.split()
                            if len(parts) == w and all(p.isdigit() for p in parts):
                                valid_rows.append([int(x) for x in parts])
                                row_count += 1
                        else:
                            break

                    if valid_rows:
                        grids[current_key] = {'h': h, 'w': w, 'rows': valid_rows}
                        print(f"Found {key}: {h}x{w}, {len(valid_rows)} rows")

        except:
            pass

    print(f"\nTotal grids loaded: {len(grids)}")
    for k in sorted(grids.keys()):
        g = grids[k]
        print(f"  {k}: {g['h']}x{g['w']}, rows={g['rows'][:2]}...")

